using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Runtime.CompilerServices;
using System.Threading;
using System.Threading.Tasks;

namespace DistributedQueryEngine
{
    // ==========================================
    // 0. DATA MODELS & UTILITIES
    // ==========================================

    public readonly struct TupleRecord : IEquatable<TupleRecord>
    {
        public long Key { get; }
        public long Value { get; }

        public TupleRecord(long key, long value)
        {
            Key = key;
            Value = value;
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public void Write(BinaryWriter writer)
        {
            writer.Write(Key);
            writer.Write(Value);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public static TupleRecord Read(BinaryReader reader)
        {
            return new TupleRecord(reader.ReadInt64(), reader.ReadInt64());
        }

        public bool Equals(TupleRecord other) => Key == other.Key && Value == other.Value;
        public override bool Equals(obj? obj) => obj is TupleRecord other && Equals(other);
        public override int HashCode() => HashCode.Combine(Key, Value);
    }

    public interface IOperator : IAsyncEnumerable<TupleRecord>
    {
        Task OpenAsync(CancellationToken cancellationToken);
        Task CloseAsync();
    }

    // ==========================================
    // 1. NETWORK EXCHANGE OPERATOR
    // ==========================================

    public sealed class NetworkExchangeServer : IDisposable
    {
        private readonly TcpListener _listener;
        private readonly Func<int, IAsyncEnumerable<TupleRecord>> _partitionStreamProvider;
        private CancellationTokenSource? _cts;
        private Task? _serverTask;

        public NetworkExchangeServer(int port, Func<int, IAsyncEnumerable<TupleRecord>> partitionStreamProvider)
        {
            _listener = new TcpListener(IPAddress.Any, port);
            _partitionStreamProvider = partitionStreamProvider;
        }

        public void Start()
        {
            _cts = new CancellationTokenSource();
            _listener.Start();
            _serverTask = Task.Run(() => AcceptLoopAsync(_cts.Token));
        }

        private async Task AcceptLoopAsync(CancellationToken token)
        {
            try
            {
                while (!token.IsCancellationRequested)
                {
                    var client = await _listener.AcceptTcpClientAsync(token);
                    _ = Task.Run(() => HandleClientAsync(client, token), token);
                }
            }
            catch (ObjectDisposedException) { }
            catch (Exception ex) when (!token.IsCancellationRequested)
            {
                Console.WriteLine($"[ExchangeServer] Error in accept loop: {ex.Message}");
            }
        }

        private async Task HandleClientAsync(TcpClient client, CancellationToken token)
        {
            using (client)
            await using (var networkStream = client.GetStream())
            using (var reader = new BinaryReader(networkStream, System.Text.Encoding.UTF8, leaveOpen: true))
            using (var writer = new BinaryWriter(networkStream, System.Text.Encoding.UTF8, leaveOpen: true))
            {
                try
                {
                    int partitionId = reader.ReadInt32();
                    var stream = _partitionStreamProvider(partitionId);

                    await foreach (var record in stream.WithCancellation(token))
                    {
                        writer.Write(true);
                        record.Write(writer);
                    }
                    writer.Write(false);
                    await writer.FlushAsync(token);
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"[ExchangeServer] Error servicing partition stream: {ex.Message}");
                }
            }
        }

        public void Dispose()
        {
            _cts?.Cancel();
            _listener.Stop();
            _cts?.Dispose();
        }
    }

    public sealed class NetworkExchangeClientOperator : IOperator
    {
        private readonly string _remoteHost;
        private readonly int _remotePort;
        private readonly int _partitionId;
        private TcpClient? _client;
        private NetworkStream? _stream;
        private BinaryReader? _reader;

        public NetworkExchangeClientOperator(string remoteHost, int remotePort, int partitionId)
        {
            _remoteHost = remoteHost;
            _remotePort = remotePort;
            _partitionId = partitionId;
        }

        public async Task OpenAsync(CancellationToken cancellationToken)
        {
            _client = new TcpClient();
            await _client.ConnectAsync(_remoteHost, _remotePort, cancellationToken);
            _stream = _client.GetStream();
            _reader = new BinaryReader(_stream);

            var writer = new BinaryWriter(_stream);
            writer.Write(_partitionId);
            await writer.FlushAsync(cancellationToken);
        }

        public async IAsyncEnumerable<TupleRecord> GenerateAsyncEnumerable([EnumeratorCancellation] CancellationToken cancellationToken = default)
        {
            if (_reader == null) throw new InvalidOperationException("Operator not opened.");

            while (_reader.ReadBoolean())
            {
                cancellationToken.ThrowIfCancellationRequested();
                yield return TupleRecord.Read(_reader);
            }
            await Task.CompletedTask;
        }

        public IAsyncEnumerator<TupleRecord> GetAsyncEnumerator(CancellationToken cancellationToken = default)
        {
            return GenerateAsyncEnumerable(cancellationToken).GetAsyncEnumerator(cancellationToken);
        }

        public Task CloseAsync()
        {
            _reader?.Dispose();
            _stream?.Dispose();
            _client?.Dispose();
            return Task.CompletedTask;
        }
    }

    // ==========================================
    // 2. DISK SPILL MANAGER
    // ==========================================

    public sealed class DiskSpillManager : IDisposable
    {
        private readonly string _spillDirectory;
        private readonly List<string> _spilledFiles = new();

        public DiskSpillManager(string? spillDirectory = null)
        {
            _spillDirectory = spillDirectory ?? Path.Combine(Path.GetTempPath(), "QueryEngineSpills", Guid.NewGuid().ToString());
            Directory.CreateDirectory(_spillDirectory);
        }

        public async Task<string> SpillPartitionAsync(IEnumerable<TupleRecord> records, CancellationToken cancellationToken = default)
        {
            string filePath = Path.Combine(_spillDirectory, $"spill_{Guid.NewGuid()}.dat");
            lock (_spilledFiles)
            {
                _spilledFiles.Add(filePath);
            }

            await using (var fs = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileShare.None, 65536, useAsync: true))
            using (var writer = new BinaryWriter(fs))
            {
                foreach (var record in records)
                {
                    cancellationToken.ThrowIfCancellationRequested();
                    record.Write(writer);
                }
                await fs.FlushAsync(cancellationToken);
            }

            return filePath;
        }

        public async IAsyncEnumerable<TupleRecord> ReadSpillAsync(string filePath, [EnumeratorCancellation] CancellationToken cancellationToken = default)
        {
            if (!File.Exists(filePath)) yield break;

            await using var fs = new FileStream(filePath, FileMode.Open, FileAccess.Read, FileShare.Read, 65536, useAsync: true);
            using var reader = new BinaryReader(fs);

            while (fs.Position < fs.Length)
            {
                cancellationToken.ThrowIfCancellationRequested();
                yield return TupleRecord.Read(reader);
            }
        }

        public void Dispose()
        {
            lock (_spilledFiles)
            {
                foreach (var file in _spilledFiles)
                {
                    try { if (File.Exists(file)) File.Delete(file); } catch { }
                }
                _spilledFiles.Clear();
            }

            try 
            { 
                if (Directory.Exists(_spillDirectory)) 
                    Directory.Delete(_spillDirectory, recursive: true); 
            } 
            catch { }
        }
    }

    // ==========================================
    // 3. HASH AGGREGATION OPERATOR
    // ==========================================

    public sealed class HashAggregationOperator : IOperator
    {
        private readonly IOperator _child;
        private readonly long _memoryLimitBytes;
        private readonly DiskSpillManager _spillManager;

        // In-memory hash table tracking [Key -> Aggregate Accumulator (Sum)]
        private readonly Dictionary<long, long> _hashTable = new();
        private long _currentMemoryUsageBytes = 0;
        private bool _isSpilled = false;
        private readonly List<string> _spilledFiles = new();

        // Size estimation: Key (8 bytes) + Value (8 bytes) + Dictionary Overhead Node (~32 bytes) = 48 bytes
        private const int EstimatedBytesPerEntry = 48;

        public HashAggregationOperator(IOperator child, long memoryLimitBytes, DiskSpillManager spillManager)
        {
            _child = child;
            _memoryLimitBytes = memoryLimitBytes;
            _spillManager = spillManager;
        }

        public async Task OpenAsync(CancellationToken cancellationToken)
        {
            await _child.OpenAsync(cancellationToken);

            // Phase 1: Consume child stream, aggregate, and spill to disk if memory exceeds limits
            await foreach (var record in _child.WithCancellation(cancellationToken))
            {
                InsertOrAggregate(record.Key, record.Value);

                if (!_isSpilled && _currentMemoryUsageBytes > _memoryLimitBytes)
                {
                    await SpillCurrentTableAsync(cancellationToken);
                }
            }

            await _child.CloseAsync();

            // Phase 2: If spilled, we must perform an external merge/re-aggregation pass
            if (_isSpilled)
            {
                await MergeSpilledPartitionsAsync(cancellationToken);
            }
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        private void InsertOrAggregate(long key, long value)
        {
            if (_hashTable.TryGetValue(key, out long existingValue))
            {
                _hashTable[key] = existingValue + value;
            }
            else
            {
                _hashTable[key] = value;
                _currentMemoryUsageBytes += EstimatedBytesPerEntry;
            }
        }

        private async Task SpillCurrentTableAsync(CancellationToken cancellationToken)
        {
            Console.WriteLine($"[HashAgg] Memory limit ({_memoryLimitBytes} bytes) exceeded. Spilling to disk...");
            var recordsToSpill = _hashTable.Select(kvp => new TupleRecord(kvp.Key, kvp.Value)).ToList();
            string spillFile = await _spillManager.SpillPartitionAsync(recordsToSpill, cancellationToken);

            lock (_spilledFiles)
            {
                _spilledFiles.Add(spillFile);
            }

            _hashTable.Clear();
            _currentMemoryUsageBytes = 0;
            _isSpilled = true;
        }

        private async Task MergeSpilledPartitionsAsync(CancellationToken cancellationToken)
        {
            // Flush any remaining in-memory elements as a final spill file
            if (_hashTable.Count > 0)
            {
                var finalMemoryRecords = _hashTable.Select(kvp => new TupleRecord(kvp.Key, kvp.Value));
                string finalSpill = await _spillManager.SpillPartitionAsync(finalMemoryRecords, cancellationToken);
                lock (_spilledFiles) { _spilledFiles.Add(finalSpill); }
                _hashTable.Clear();
            }

            // Re-read all spill files and compute final hash aggregations
            foreach (var file in _spilledFiles)
            {
                await foreach (var record in _spillManager.ReadSpillAsync(file, cancellationToken))
                {
                    InsertOrAggregate(record.Key, record.Value);
                }
            }
        }

        public async IAsyncEnumerable<TupleRecord> GenerateAsyncEnumerable([EnumeratorCancellation] CancellationToken cancellationToken = default)
        {
            foreach (var kvp in _hashTable)
            {
                cancellationToken.ThrowIfCancellationRequested();
                yield return new TupleRecord(kvp.Key, kvp.Value);
            }
            await Task.CompletedTask;
        }

        public IAsyncEnumerator<TupleRecord> GetAsyncEnumerator(CancellationToken cancellationToken = default)
        {
            return GenerateAsyncEnumerable(cancellationToken).GetAsyncEnumerator(cancellationToken);
        }

        public Task CloseAsync()
        {
            _hashTable.Clear();
            return Task.CompletedTask;
        }
    }

    // ==========================================
    // 4. MOCK DATA SOURCE OPERATOR
    // ==========================================

    public sealed class MemoryTableOperator : IOperator
    {
        private readonly List<TupleRecord> _data;

        public MemoryTableOperator(IEnumerable<TupleRecord> data)
        {
            _data = new List<TupleRecord>(data);
        }

        public Task OpenAsync(CancellationToken cancellationToken) => Task.CompletedTask;

        public async IAsyncEnumerable<TupleRecord> GenerateAsyncEnumerable([EnumeratorCancellation] CancellationToken cancellationToken = default)
        {
            foreach (var record in _data)
            {
                cancellationToken.ThrowIfCancellationRequested();
                yield return record;
            }
            await Task.CompletedTask;
        }

        public IAsyncEnumerator<TupleRecord> GetAsyncEnumerator(CancellationToken cancellationToken = default)
        {
            return GenerateAsyncEnumerable(cancellationToken).GetAsyncEnumerator(cancellationToken);
        }

        public Task CloseAsync() => Task.CompletedTask;
    }

    // ==========================================
    // 5. VERIFICATION HARNESS
    // ==========================================

    public static class Program
    {
        public static async Task Main(string[] args)
        {
            Console.WriteLine("=== INITIALIZING DISTRIBUTED QUERY ENGINE MODULES ===");

            // Generate synthetic dataset designed to breach strict memory limits to trigger disk spilling
            var rawData = new List<TupleRecord>();
            for (int i = 0; i < 100_000; i++)
            {
                long key = i % 500; // 500 unique keys, high cardinality grouping repetition
                rawData.Add(new TupleRecord(key, 1));
            }

            var baseSource = new MemoryTableOperator(rawData);

            // Configure strict memory limit (e.g., 200KB) to force Disk Spill Manager intervention
            long strictMemoryLimitBytes = 200 * 1024; 

            using var spillManager = new DiskSpillManager();
            var hashAggregator = new HashAggregationOperator(baseSource, strictMemoryLimitBytes, spillManager);

            // Test execution cycle
            CancellationTokenSource cts = new CancellationTokenSource();

            Console.WriteLine("Executing Hash Aggregation Query Plan with Disk Spilling...");
            await hashAggregator.OpenAsync(cts.Token);

            int outputCount = 0;
            long totalAggregatedRows = 0;

            await foreach (var result in hashAggregator.WithCancellation(cts.Token))
            {
                outputCount++;
                totalAggregatedRows += result.Value;
                // Print a small sample
                if (outputCount <= 5)
                {
                    Console.WriteLine($"[Result] Group Key: {result.Key} -> Aggregate Sum: {result.Value}");
                }
            }

            await hashAggregator.CloseAsync();

            Console.WriteLine($"\nExecution Complete.");
            Console.WriteLine($"Total Unique Groups Emitted: {outputCount} (Expected: 500)");
            Console.WriteLine($"Total Aggregated Values Sum: {totalAggregatedRows} (Expected: 100,000)");

            // Network Exchange Operator integration check
            Console.WriteLine("\nValidating Network Exchange Operator over TCP Loopback...");
            int testPort = 5055;
            using var server = new NetworkExchangeServer(testPort, partitionId => 
            {
                // Serve partition data dynamically
                return new MemoryTableOperator(new[] { new TupleRecord(partitionId, 999) });
            });

            server.Start();

            using var clientOp = new NetworkExchangeClientOperator("127.0.0.1", testPort, partitionId: 42);
            await clientOp.OpenAsync(cts.Token);

            await foreach (var remoteRecord in clientOp)
            {
                Console.WriteLine($"[Network Exchange] Received Partition Record -> Key: {remoteRecord.Key}, Value: {remoteRecord.Value}");
            }
            await clientOp.CloseAsync();
            Console.WriteLine("All modules verified successfully.");
        }
    }
}
```

### Architecture Overview

1. **Network Exchange Operator**: Uses binary framing (`BinaryReader`/`BinaryWriter`) over raw TCP streams (`TcpListener`/`TcpClient`) to asynchronously stream ordered partitions across cluster nodes without intermediate JSON/Serialization bottlenecks.
2. **Hash Aggregation Operator**: Accumulates keys/values dynamically in a compact dictionary. It traces memory accumulation using vectorized entry byte estimation (`48 bytes/entry`). 
3. **Disk Spill Manager**: Automatically intercepts the execution pipeline when the memory consumption exceeds the configured allocation barrier. It dumps the active dictionary partitions asynchronously into isolated unbuffered files using managed `FileStream` objects, and merges them using an external re-reading stream pass.

Here is a robust, thread-safe implementation of the Singleton pattern in C# using **double-check locking** and **lazy initialization**. 

This approach ensures that thread synchronization overhead only happens during the first instantiation, and it is fully thread-safe without relying solely on the `Lazy<T>` class (to strictly demonstrate the double-check locking mechanism).

### C# Implementation

```csharp
using System;

public sealed class Singleton
{
    // Volatile ensures that assignment to the instance variable 
    // completes before the instance variable can be accessed.
    // This prevents compiler/CPU instruction reordering.
    private static volatile Singleton? _instance;

    // A lock object for thread synchronization. 
    // Never lock on the 'typeof(Singleton)' type directly to avoid deadlocks.
    private static readonly object _lock = new object();

    // Counter to prove that only one instance is ever created
    private static int _counter = 0;

    // Private constructor prevents instantiation from outside the class.
    private Singleton()
    {
        _counter++;
        Console.WriteLine($"Singleton instance created. Count: {_counter}");
    }

    // Public property to get the instance
    public static Singleton Instance
    {
        get
        {
            // First check (no lock) - improves performance by avoiding 
            // the lock once the instance is already initialized.
            if (_instance == null)
            {
                // Acquire lock for thread safety
                lock (_lock)
                {
                    // Second check (with lock) - ensures that if two threads 
                    // passed the first check simultaneously, only one creates the instance.
                    if (_instance == null)
                    {
                        _instance = new Singleton();
                    }
                }
            }

            return _instance;
        }
    }

    public void DoSomething()
    {
        Console.WriteLine("Singleton is doing something.");
    }
}
```

### How to Test It

You can test the thread-safety of this implementation using `Parallel.Invoke`, which simulates multiple threads trying to access the Singleton simultaneously:

```csharp
class Program
{
    static void Main(string[] args)
    {
        // Simulate 10 threads trying to access the Singleton at the exact same time
        Parallel.For(0, 10, i =>
        {
            Singleton singleton = Singleton.Instance;
            singleton.DoSomething();
        });

        Console.ReadKey();
    }
}
```

### Output:
```text
Singleton instance created. Count: 1
Singleton is doing something.
Singleton is doing something.
Singleton is doing something.
... (repeated 10 times, but the constructor only runs once)
```

### Key Design Details:
1. **`sealed` Class**: Prevents other classes from inheriting from it. Inheritance can break the Singleton pattern by allowing subclasses to create instances.
2. **Private Constructor**: Restricts instantiation to within the class itself.
3. **`volatile` Keyword**: Essential in C# memory models. It ensures that the read and write operations to `_instance` directly access memory, preventing issues where a thread sees a half-constructed object due to CPU instruction reordering.
4. **Double-Check (`if` statements)**: 
   * The **first check** avoids the expensive `lock` overhead every single time a caller requests the instance.
   * The **second check** guarantees that inside the locked block, only one thread actually instantiates the object.

Here is a complete, production-ready implementation of a generic `Stack<T>` in C# backed by a dynamic array. 

It includes automatic resizing (doubling when full, halving when too empty to save memory), input validation, generic constraints awareness, and implements `IEnumerable<T>` so you can use it in `foreach` loops.

### The Code

```csharp
using System;
using System.Collections;
using System.Collections.Generic;

public class CustomStack<T> : IEnumerable<T>
{
    private T[] _array;
    private int _size;
    private const int DefaultCapacity = 4;

    /// <summary>
    /// Gets the number of elements contained in the Stack.
    /// </summary>
    public int Count => _size;

    /// <summary>
    /// Gets the total number of elements the internal array can hold without resizing.
    /// </summary>
    public int Capacity => _array.Length;

    /// <summary>
    /// Initializes a new instance of the CustomStack class that is empty and has the default initial capacity.
    /// </summary>
    public CustomStack()
    {
        _array = new T[DefaultCapacity];
        _size = 0;
    }

    /// <summary>
    /// Initializes a new instance of the CustomStack class that is empty and has the specified initial capacity.
    /// </summary>
    public CustomStack(int capacity)
    {
        if (capacity < 0)
            throw new ArgumentOutOfRangeException(nameof(capacity), "Capacity must be non-negative.");

        _array = new T[Math.Max(capacity, DefaultCapacity)];
        _size = 0;
    }

    /// <summary>
    /// Inserts an object at the top of the CustomStack.
    /// </summary>
    public void Push(T item)
    {
        if (_size == _array.Length)
        {
            // Double the capacity when the array is full
            Resize(_array.Length * 2);
        }

        _array[_size++] = item;
    }

    /// <summary>
    /// Removes and returns the object at the top of the CustomStack.
    /// </summary>
    public T Pop()
    {
        if (_size == 0)
            throw new InvalidOperationException("Stack is empty.");

        int topIndex = --_size;
        T item = _array[topIndex];

        // Clear the reference to allow Garbage Collection
        _array[topIndex] = default!; 

        // Optional: Shrink array if it's only 25% full to save memory
        if (_size > DefaultCapacity && _size < _array.Length / 4)
        {
            Resize(_array.Length / 2);
        }

        return item;
    }

    /// <summary>
    /// Returns the object at the top of the CustomStack without removing it.
    /// </summary>
    public T Peek()
    {
        if (_size == 0)
            throw new InvalidOperationException("Stack is empty.");

        return _array[_size - 1];
    }

    /// <summary>
    /// Removes all objects from the CustomStack.
    /// </summary>
    public void Clear()
    {
        // Clear elements so GC can reclaim memory
        Array.Clear(_array, 0, _size);
        _size = 0;
    }

    /// <summary>
    /// Determines whether an element is in the CustomStack.
    /// </summary>
    public bool Contains(T item)
    {
        EqualityComparer<T> comparer = EqualityComparer<T>.Default;
        for (int i = 0; i < _size; i++)
        {
            if (comparer.Equals(_array[i], item))
            {
                return true;
            }
        }
        return false;
    }

    /// <summary>
    /// Helper method to resize the internal array.
    /// </summary>
    private void Resize(int newCapacity)
    {
        T[] newArray = new T[newCapacity];
        Array.Copy(_array, 0, newArray, 0, _size);
        _array = newArray;
    }

    /// <summary>
    /// Returns an enumerator that iterates through the CustomStack (LIFO order).
    /// </summary>
    public IEnumerator<T> GetEnumerator()
    {
        // Iterate from top to bottom
        for (int i = _size - 1; i >= 0; i--)
        {
            yield return _array[i];
        }
    }

    IEnumerator IEnumerable.GetEnumerator()
    {
        return GetEnumerator();
    }
}
```

### Example Usage

```csharp
class Program
{
    static void Main()
    {
        CustomStack<string> stack = new CustomStack<string>();

        // Pushing elements
        stack.Push("First");
        stack.Push("Second");
        stack.Push("Third");

        Console.WriteLine($"Count: {stack.Count}, Capacity: {stack.Capacity}"); // Count: 3, Capacity: 4

        // Peeking
        Console.WriteLine($"Top element: {stack.Peek()}"); // Third

        // Popping elements (LIFO order)
        Console.WriteLine($"Popped: {stack.Pop()}"); // Third
        Console.WriteLine($"Popped: {stack.Pop()}"); // Second

        // Using foreach (Enumerates from top to bottom)
        stack.Push("Fourth");
        Console.WriteLine("\nCurrent Stack contents:");
        foreach (var item in stack)
        {
            Console.WriteLine(item);
        }
        // Output: 
        // Fourth
        // First
    }
}
```

### Key Design Features:
1. **Dynamic Resizing (Amortized $O(1)$ insertions):** When the stack exceeds its capacity, `Array.Copy` is used to double the array size. This ensures `Push` runs in amortized constant time.
2. **Memory Leak Prevention (`_array[topIndex] = default!`):** In C#, reference types stored in an array will keep holding memory references even after "removal" unless explicitly nulled out. Setting it to `default!` allows the Garbage Collector to clean up abandoned objects.
3. **Memory Shrinking:** The stack halves its internal array size if utilization drops below 25%, preventing memory bloat after large operations.
4. **`IEnumerable<T>` Implementation:** Allows integration with LINQ and standard `foreach` loops, traversing from the top of the stack down to the bottom.

Building a secure, fast, and extensible authentication system for an existing application requires a layered architecture. Since I don't know your specific stack (e.g., Node.js, Python, PostgreSQL, MongoDB), I will provide a **production-grade architectural blueprint and implementation pattern** that you can adapt to your technology stack.

---

### 1. High-Level Architecture

To make it **fast**, we will minimize database hits during routine API requests by using stateless JWTs (JSON Web Tokens) with a short lifespan, backed by Redis for session revocation and rate limiting.

To make it **secure**, we will use industry standards: OAuth 2.0 / OIDC for social logins, Argon2 for password hashing, and HttpOnly cookies for token storage to prevent XSS attacks.

```
[ Client (Web/Mobile) ]
   │
   ├─► /auth/login (Email/Password) ──► [ Auth Service ] ──► [ Existing DB ]
   ├─► /auth/oauth/google          ──► [ Google OIDC ]          │
   └─► API Request + Cookie        ──► [ API Gateway ] ◄────────┘
                                            │
                                    (Verify JWT & Redis)
```

---

### 2. Database Integration Strategy

Since you have an **existing database**, we shouldn't force a rigid schema on you. Instead, define a flexible `users` and `identities` schema pattern.

#### Recommended Database Schema (SQL Example)
```sql
-- Core user table (agnostic of login method)
CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email VARCHAR(255) UNIQUE NOT NULL,
    email_verified BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- Handles multiple login methods (Password, Google, Apple, etc.)
CREATE TABLE user_identities (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID REFERENCES users(id) ON DELETE CASCADE,
    provider VARCHAR(50) NOT NULL, -- 'email', 'google', 'apple', 'github'
    provider_id VARCHAR(255) NOT NULL, -- password hash (if provider='email') or OAuth Subject ID
    password_hash VARCHAR(255), -- NULL if social login
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    UNIQUE(provider, provider_id)
);
```
*Why this works with an existing DB:* If you already have a `users` table, you only need to create a secondary `user_identities` table and migrate existing passwords into it.

---

### 3. Supporting Multiple Login Methods

#### A. Email & Password (Traditional)
*   **Registration:** Hash the password using **Argon2id** (preferred over bcrypt for better resistance to GPU cracking).
*   **Login:** Verify the password hash, then issue tokens.

#### B. Social Logins (Google, Apple, GitHub, etc.)
*   Use standard **OAuth 2.0 / OpenID Connect (OIDC)**.
*   **Flow:**
    1. Client redirects to Google.
    2. Google redirects back with an authorization code.
    3. Your backend exchanges the code for Google user info (email, name, sub ID).
    4. **Account Linking:** Check if a user with that email already exists. If yes, link the new `user_identity` to the existing user. If no, create a new user and identity.

---

### 4. Security Implementation Details

1.  **Token Strategy (Access + Refresh Tokens):**
    *   **Access Token:** JWT, valid for **15 minutes**. Stored in memory on the client (or HttpOnly cookie). Sent with every API request.
    *   **Refresh Token:** Long-lived (e.g., 7 days), stored securely in an **HttpOnly, Secure, SameSite=Strict cookie**. Used *only* to get a new access token at `/auth/refresh`.
2.  **CSRF & XSS Protection:**
    *   By using `HttpOnly` cookies for tokens, JavaScript cannot read them, mitigating XSS token theft.
    *   Use `SameSite=Strict` or `Lax` to prevent Cross-Site Request Forgery.
3.  **Rate Limiting (Speed & Brute-Force Protection):**
    *   Use **Redis** to limit login attempts (e.g., max 5 attempts per 15 minutes per IP/email) to prevent credential stuffing.

---

### 5. Making It "Fast"

1.  **Stateless Verification:** Microservices or API routes verify the JWT signature cryptographically using a Public/Private key pair (RS256) without hitting the database on every request.
2.  **Caching User Status:** Store user roles and active status in Redis. If a user is banned, check Redis instantly rather than running a heavy SQL query.
3.  **Edge/CDN Offloading:** If using serverless or edge functions (Cloudflare Workers, Vercel Edge), handle token validation at the edge nearest the user.

---

### 6. Reference Implementation (Node.js / Express Pseudo-code)

Here is how a fast, secure login endpoint looks in practice:

```javascript
const express = require('express');
const argon2 = require('argon2');
const jwt = require('jsonwebtoken');
const db = require('./db'); // Your existing database connection
const router = express.Router();

router.post('/auth/login', async (req, res) => {
    const { email, password } = req.body;

    try {
        // 1. Fast lookup using existing DB + Identity table
        const query = `
            SELECT u.id, u.email, ui.password_hash 
            FROM users u
            JOIN user_identities ui ON u.id = ui.user_id
            WHERE u.email = $1 AND ui.provider = 'email'
        `;
        const result = await db.query(query, [email]);
        const user = result.rows[0];

        if (!user) {
            return res.status(401).json({ error: 'Invalid credentials' });
        }

        // 2. Secure password verification (takes ~50ms)
        const validPassword = await argon2.verify(user.password_hash, password);
        if (!validPassword) {
            return res.status(401).json({ error: 'Invalid credentials' });
        }

        // 3. Issue fast, stateless Access Token (15 mins)
        const accessToken = jwt.sign(
            { userId: user.id, email: user.email }, 
            process.env.JWT_SECRET, 
            { expiresIn: '15m' }
        );

        // 4. Issue secure Refresh Token via HttpOnly Cookie
        const refreshToken = jwt.sign(
            { userId: user.id }, 
            process.env.JWT_REFRESH_SECRET, 
            { expiresIn: '7d' }
        );

        res.cookie('refreshToken', refreshToken, {
            httpOnly: true,
            secure: process.env.NODE_ENV === 'production',
            sameSite: 'strict',
            maxAge: 7 * 24 * 60 * 60 * 1000 // 7 days
        });

        return res.json({ accessToken, message: 'Login successful' });

    } catch (err) {
        console.error(err);
        return res.status(500).json({ error: 'Internal server error' });
    }
});
```

---

### Next Steps to Implement This:
1. **Audit your current DB:** Run the `user_identities` migration script.
2. **Choose your libraries:** 
   * *Node.js:* `argon2`, `jsonwebtoken`, `passport.js` (for social logins).
   * *Python/FastAPI:* `passlib[argon2]`, `PyJWT`, `Authlib`.
   * *Go:* `crypto/bcrypt` or `argon2`, `golang-jwt`.
3. **Configure Environment Variables:** Ensure `JWT_SECRET` and database credentials are securely stored (e.g., AWS Secrets Manager, Vault, or `.env`).

Building a notification system that hits all your requirements—timely, targeted, multi-channel, and spam-free—requires a decoupled, event-driven architecture. 

Here is a blueprint for building a production-grade notification system.

---

### Phase 1: Architecture & Core Components

To avoid spamming and ensure timely delivery, your system needs six core components:

1. **Event Sources (The Triggers):** Services in your app that say, *"Something happened"* (e.g., `PaymentFailed`, `NewMessage`, `SecurityAlert`).
2. **The Ingestion Queue (Kafka / RabbitMQ / AWS SQS):** Decouples event generation from processing. If your notification service goes down, events aren't lost; they wait in the queue.
3. **The Routing & Decision Engine (The Brain):** The core service that answers three questions:
   * *Who* needs to receive this?
   * *How* should they receive it (Email, SMS, Push, In-App)?
   * *Should* they receive it right now (Rate limiting, preferences, quiet hours)?
4. **User Preferences & State Store (Redis + PostgreSQL):** Stores user settings (e.g., "Mute push notifications after 10 PM") and state for anti-spam (e.g., "Has this user been emailed about this in the last hour?").
5. **Channel Dispatchers (The Workers):** Pluggable microservices or worker pools that talk to third-party APIs (SendGrid for email, Twilio for SMS, Firebase for Push).
6. **Delivery Log / Analytics:** Tracks sent, delivered, opened, and failed statuses.

---

### Phase 2: Solving the Core Challenges

#### 1. Delivering "Timely Alerts"
* **Use Event-Driven Architecture:** Do not poll databases. When an event occurs, push it to a message queue immediately.
* **Priority Queues:** Split your queue into tiers. 
  * *P0 (Urgent):* Security alerts, password resets (process instantly).
  * *P1 (Standard):* Direct messages, order updates (process within seconds).
  * *P2 (Batch/Marketing):* Digests, newsletters (process during off-peak hours).

#### 2. Reaching "The Right Users"
* **Dynamic User Graph:** Don't hardcode rules. Use a template system where events contain metadata, and the Routing Engine resolves recipients dynamically.
* **Role/Context-Based Routing:** An event like `ServerDown` might route to SMS for *On-Call Engineers*, Slack for the *DevOps Channel*, and Dashboard for *Engineering Managers*.

#### 3. Multi-Channel Orchestration (The Fallback Chain)
Users miss push notifications; emails end up in spam. Use a **Waterfall Strategy**:
1. Try the user's preferred channel first (e.g., Push).
2. Wait X minutes (e.g., 5 minutes).
3. Check if the notification was marked as "Read" or "Clicked."
4. If not, fallback to the secondary channel (e.g., Email).
5. If still unread and urgent, fallback to SMS.

#### 4. Preventing "Spam" (The Anti-Spam Engine)
This is where most notification systems fail. Implement these four layers of defense in your Routing Engine:

* **User Preferences (Opt-in/Opt-out):** Respect granular settings. If a user turns off marketing emails, the engine drops the event instantly.
* **Quiet Hours / Timezones:** If a non-urgent alert triggers at 3:00 AM in the user's local timezone, hold it in a Redis delayed queue until 8:00 AM.
* **Rate Limiting (Token Bucket / Redis):** 
  * *Global limit:* No user receives more than $X$ notifications per hour.
  * *Category limit:* No more than 1 promotional alert per day.
* **Smart Batching / Digests:** Instead of sending 10 individual emails for 10 new comments, aggregate them into a single digest: *"You have 10 new comments on your post."*
* **Deduplication:** If the same event fires 5 times in 10 seconds (e.g., rapid-fire button clicks), use a Redis `SETNX` lock with a TTL (e.g., 60 seconds) to process it only once.

